from src.stats import mean, median, mode


class TestStats(unittest.TestCase):
    def test_mean(self):
        self.assertEqual(mean([1, 2, 3, 4]), 2.5)

    def test_median_odd(self):
        self.assertEqual(median([3, 1, 2]), 2)

    def test_median_even(self):
        self.assertEqual(median([1, 2, 3, 4]), 2.5)

    def test_mode(self):
        self.assertEqual(mode([1, 2, 2, 3, 3]), 2)
        self.assertEqual(mode([3, 3, 2, 2, 1]), 2)
        self.assertEqual(mode([1]), 1)
        self.assertEqual(mode([1, 1, 1, 2, 2, 2, 3]), 1)
        self.assertEqual(mode([4, 4, 4, 5, 5, 5, 5]), 5)
